def f(n):
    """Calculates f(n), the largest odd divisor of n."""
    while n > 0 and n % 2 == 0:
        n //= 2
    return n

def check_condition(u, v):
    """Checks if the condition holds for given u and v."""
    if v <= 0 or u <= 0:
        return False

    # We need to check v conditions, indexed by i from 0 to v-1.
    # Condition i: f(u + v + i) - f(u + i) is a multiple of 4.
    for i in range(v):
        term1 = f(u + v + i)
        term2 = f(u + i)
        difference = term1 - term2

