def f(n):
    """Calculates f(n) = n / 2^m, where m is the exponent of 2 in n."""
    if n <= 0:
        raise ValueError("n must be positive")
    m = 0
    temp_n = n
    while temp_n > 0 and temp_n % 2 == 0:
        m += 1
        temp_n //= 2
    return temp_n

def check_condition(u, v):
    """Checks if the condition holds for a given u and v."""
    if v <= 0 or u <= 0:
        return False

    # We need to check f(n+v) - f(n) is a multiple of 4 for n = u, u+1, ..., u+v-1
    for n in range(u, u + v):
        diff = f(n + v) - f(n)
        if diff % 4 != 0:
